public class DevTestDoublePairingProofVerifier implements PairingProofVerifier {
    private final Set<String> usedNonces = ConcurrentHashMap.newKeySet();
    public Result verify(...) {
        if (proof == null || proof.isBlank()) return Result.failed(MISSING);
        Decoded d = DevProofCodec.decode(proof);
        if (d == null) return Result.failed(MALFORMED);
        if (!DevProofCodec.VERSION.equals(d.version())) return Result.failed(UNSUPPORTED_VERSION);
        if (!d.signatureValid()) return Result.failed(BAD_SIGNATURE);
        Map<String,Object> p = d.payload();
        if (!"pairing".equals(DeviceJson.textAt(p,"purpose"))) return MALFORMED;
        Long exp = DeviceJson.longAt(p,"exp");
        if (exp == null) return MALFORMED;
        if (exp <= Instant.now().getEpochSecond()) return EXPIRED;
        if (!expectedGimbalId.toString().equals(DeviceJson.textAt(p,"gimbalId"))) return WRONG_GIMBAL;
        if (!accountId.toString().equals(DeviceJson.textAt(p,"accountId"))
            || !installationId.equals(DeviceJson.textAt(p,"installationId"))) return WRONG_ACCOUNT;
        String nonce = DeviceJson.textAt(p,"nonce");
        if (nonce == null || nonce.isBlank()) return MALFORMED;
        if (!usedNonces.add(nonce)) return NONCE_REPLAY;
        return Result.valid();
    }
}
