        if (!gimbalId.equals(principal.gimbalUuid())) throw notVisible();
        long seq = parseBigint(body.observationSeq());
        return txTemplate.execute(status -> reportLocked(principal, gimbalId, body, seq));
    }

    private Result reportLocked(...) {
        Row row = loadForUpdate(gimbalId);
        if (row == null) throw notVisible();
        if (row.credentialVersion() != principal.credentialVersion()) throw new ApiException(SESSION_INVALID, "gimbal session credential generation is no longer current");
        Map<String,Object> obs = DeviceJson.parseObject(row.latestObservation());
        String epoch = DeviceJson.textAt(obs, "observation_epoch");
        Long prevSeq = DeviceJson.longAt(obs, "observation_seq");
        boolean accepted = epoch == null || !epoch.equals(body.observationEpoch())
                || (prevSeq == null || seq > prevSeq);
        if (!accepted) return new Result(false, row.lastSeenAt(), row.statusRevision());
        Instant now = Instant.now();
        Map<String,Object> activeIncidents = DeviceJson.parseObject(row.activeIncidents());
        EpisodeOutcome episodes = mergeEpisodes(activeIncidents, body, seq, now);
        Map<String,Object> latest = new LinkedHashMap<>();
        latest.put("schema_version", 1);
        latest.put("observation_epoch", body.observationEpoch());
        latest.put("observation_seq", seq);
        latest.put("power_state", body.powerState().name());
        latest.put("observed_at", EnvelopeSupport.rfc3339(body.observedAt()));
        latest.put("received_at", EnvelopeSupport.rfc3339(now));
        latest.put("task_ref", body.taskId() == null ? null : body.taskId().toString());
        latest.put("execution_ref", body.executionId() == null ? null : body.executionId().toString());
        latest.put("episodes", episodes.latestEpisodes());
        Map<String,Object> active = new LinkedHashMap<>();
        active.put("schema_version", 1);
        active.put("episodes", episodes.activeEpisodes());
        String connection = "online".equals(row.connectionStatus()) ? "online" : "online";
        long statusRevision = row.statusRevision();
        if (!"online".equals(row.connectionStatus())) statusRevision = row.statusRevision() + 1;
        // Always set connection_status to online on accept (unknown/offline -> online; online stays)
        int updated = jdbc.update("UPDATE gimbals SET last_seen_at = ?, latest_observation = ?::jsonb, active_incidents = ?::jsonb, connection_status = 'online', status_revision = ?, updated_at = now() WHERE id = ? AND status_revision = ?",
            Timestamp.from(now), DeviceJson.write(latest), DeviceJson.write(active), statusRevision, gimbalId, row.statusRevision());
        if (updated == 0) throw ApiException.requestInProgress(1);
        return new Result(true, now, statusRevision);
    }
}
