private record EpisodeOutcome(Map<String,Object> latestEpisodes, Map<String,Object> activeEpisodes) {}

private EpisodeOutcome mergeEpisodes(Map<String,Object> activeIncidents, DeviceDtos.HeartbeatBody body, long seq, Instant now) {
    Map<String,Object> activeEps = DeviceJson.objectAt(activeIncidents, "episodes");
    // deep-copy active episodes into latest
    Map<String,Object> latestEps = deepCopy(activeEps);
    // ensure latest has detail + last_reported_seq keys (may be missing for legacy)
    // index active by code
    Map<String, String> activeByCode = new HashMap<>();
    for (entry : activeEps) { if state active -> activeByCode.put(code, incidentId); }
    List<Map<String,Object>> incidents = body.incidents() == null ? List.of() : body.incidents();
    for (Map<String,Object> inc : incidents) {
        String code = DeviceJson.textAt(inc, "code");
        if (code == null || code.isBlank()) continue;
        boolean clear = isClear(inc);
        if (clear) {
            String id = activeByCode.get(code);
            if (id != null) {
                markResolved(activeEps.get(id), now);
                markResolved(latestEps.get(id), now);
                activeByCode.remove(code);
            }
        } else {
            String id = activeByCode.get(code);
            if (id != null) {
                touch(latestEps.get(id), inc, seq, now);
                // active copy: update last_reported_at only
                touchActive(activeEps.get(id), now);
            } else {
                String newId = UUID.randomUUID().toString();
                Map<String,Object> full = newEpisode(newId, inc, seq, now);
                Map<String,Object> summary = summarize(full);
                latestEps.put(newId, full);
                activeEps.put(newId, summary);
                activeByCode.put(code, newId);
            }
        }
    }
    return new EpisodeOutcome(latestEps, activeEps);
}
```

