package cn.yuanxin.mvp.web.devices;

import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.test.web.servlet.MvcResult;

import java.time.Instant;
import java.util.Map;
import java.util.UUID;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;

/**
 * 测试组 1：M2-A01 云台认证（A 已实现，本 lane 只验证不修改）。
 *
 * <p>证明：合法凭据签发会话且不含成员资料；无效凭据/错 credentialVersion →
 * 401 且 T03 未被登记为在线；重复认证不创建护理执行/job/通知；credential_version
 * 递增后旧 token 立即失效；云台 token 可用于 A02/A03/A04/A05；认证不缓存
 * 凭据（带 Idempotency-Key 也不写 T13）。</p>
 */
class GimbalSessionVerificationIT extends AbstractDeviceIT {

    @Test
    @DisplayName("凭据失败不登记可信在线；成功签发不含成员资料")
    void validCredentialIssuesSessionWithoutMemberData() throws Exception {
        UUID gimbalId = seedGimbal(1L);
        Map<String, Object> before = jdbc.queryForMap(
                "SELECT last_seen_at, connection_status FROM gimbals WHERE id = ?", gimbalId);

        MvcResult ok = mockMvc.perform(post("/api/v1/gimbal-sessions")
                        .contentType("application/json")
                        .content("{\"credential\":\"" + credentialOf(gimbalId)
                                + "\",\"credentialVersion\":\"1\",\"proof\":\"dev-proof\"}"))
                .andReturn();
        assertEquals(200, ok.getResponse().getStatus(), ok.getResponse().getContentAsString());
        JsonNode data = dataOf(ok);
        assertEquals(gimbalId.toString(), data.path("gimbalId").asText());
        assertFalse(data.path("sessionToken").asText().isBlank());
        assertNotNull(data.path("expiresAt").asText(null));
        assertNotNull(data.path("serverTime").asText(null));
        // 不返回任何成员/账号资料
        assertFalse(data.has("accountId"));
        assertFalse(data.has("memberId"));
        assertFalse(data.has("phone"));

        // 凭据失败（未知凭据 / 错 credentialVersion）→ 401，T03 原值不变
        MvcResult badCredential = mockMvc.perform(post("/api/v1/gimbal-sessions")
                        .contentType("application/json")
                        .content("{\"credential\":\"ghost-credential\",\"credentialVersion\":\"1\","
                                + "\"proof\":\"dev-proof\"}"))
                .andReturn();
        assertEquals(401, badCredential.getResponse().getStatus());
        MvcResult badVersion = mockMvc.perform(post("/api/v1/gimbal-sessions")
                        .contentType("application/json")
                        .content("{\"credential\":\"" + credentialOf(gimbalId)
                                + "\",\"credentialVersion\":\"99\",\"proof\":\"dev-proof\"}"))
                .andReturn();
        assertEquals(401, badVersion.getResponse().getStatus());

        Map<String, Object> after = jdbc.queryForMap(
                "SELECT last_seen_at, connection_status FROM gimbals WHERE id = ?", gimbalId);
        assertEquals(before, after);
        assertEquals("unknown", after.get("connection_status"));
    }

    @Test
    @DisplayName("重复认证不创建 care_executions/async_jobs/notifications")
    void repeatedAuthenticationCreatesNoCareResources() throws Exception {
        UUID gimbalId = seedGimbal(1L);
        long executions = count("care_executions", "1 = 1");
        long jobs = count("async_jobs", "1 = 1");
        long notifications = count("notifications", "1 = 1");

        for (int i = 0; i < 3; i++) {
            String token = gimbalToken(gimbalId, 1L);
            assertEquals(401, mockMvc.perform(post("/api/v1/gimbal-sessions")
                            .contentType("application/json")
                            .content("{\"credential\":\"nope\",\"credentialVersion\":\"1\","
                                    + "\"proof\":\"p\"}"))
                    .andReturn().getResponse().getStatus());
            assertFalse(token.isBlank());
        }

        assertEquals(executions, count("care_executions", "1 = 1"));
        assertEquals(jobs, count("async_jobs", "1 = 1"));
        assertEquals(notifications, count("notifications", "1 = 1"));
    }

    @Test
    @DisplayName("认证不使用 Idempotency-Key 缓存凭据")
    void authenticationDoesNotUseIdempotencyKey() throws Exception {
        UUID gimbalId = seedGimbal(1L);
        for (int i = 0; i < 2; i++) {
            MvcResult result = mockMvc.perform(post("/api/v1/gimbal-sessions")
                            .header("Idempotency-Key", "cred-" + gimbalId)
                            .contentType("application/json")
                            .content("{\"credential\":\"" + credentialOf(gimbalId)
                                    + "\",\"credentialVersion\":\"1\",\"proof\":\"dev-proof\"}"))
                    .andReturn();
            assertEquals(200, result.getResponse().getStatus());
        }
        assertEquals(0, count("idempotency_requests",
                "principal_type = 'gimbal' AND operation LIKE '%gimbal%'"));
    }

    @Test
    @DisplayName("云台 token 可用于 A02/A03/A04/A05；credential_version 递增后旧 token 401")
    void tokenUsableAcrossEndpointsAndRotationInvalidates() throws Exception {
        GimbalSession session = gimbalSession();
        String token = session.accessToken();
        UUID gimbalId = session.gimbalId();

        MvcResult heartbeat = mockMvc.perform(post("/api/v1/gimbals/" + gimbalId + "/heartbeats")
                        .header("Authorization", "Bearer " + token)
                        .contentType("application/json")
                        .content(heartbeatJson("epoch-1", "1", "awake", null, null, null)))
                .andReturn();
        assertEquals(200, heartbeat.getResponse().getStatus(),
                heartbeat.getResponse().getContentAsString());
        assertTrue(dataOf(heartbeat).path("accepted").asBoolean());

        MvcResult status = mockMvc.perform(get("/api/v1/gimbals/" + gimbalId + "/status")
                        .header("Authorization", "Bearer " + token))
                .andReturn();
        assertEquals(200, status.getResponse().getStatus(), status.getResponse().getContentAsString());

        String serial = "mc-" + UUID.randomUUID();
        MvcResult observation = mockMvc.perform(post("/api/v1/microcrystal-observations")
                        .header("Authorization", "Bearer " + token)
                        .header("Idempotency-Key", "obs-" + serial)
                        .contentType("application/json")
                        .content(observationJson(serial,
                                DevProofFixture.connectionGimbal(gimbalId, serial), "e1", "1")))
                .andReturn();
        assertEquals(200, observation.getResponse().getStatus(),
                observation.getResponse().getContentAsString());
        UUID microcrystalId = UUID.fromString(dataOf(observation).path("microcrystalId").asText());

        MvcResult capabilities = mockMvc.perform(get("/api/v1/microcrystals/" + microcrystalId
                        + "/capabilities").header("Authorization", "Bearer " + token))
                .andReturn();
        assertEquals(200, capabilities.getResponse().getStatus(),
                capabilities.getResponse().getContentAsString());

        // credential_version 轮换：旧 token 立即失效（A 的 PrincipalRevalidator）。
        jdbc.update("UPDATE gimbals SET credential_version = 2 WHERE id = ?", gimbalId);
        MvcResult stale = mockMvc.perform(get("/api/v1/gimbals/" + gimbalId + "/status")
                        .header("Authorization", "Bearer " + token))
                .andReturn();
        assertEquals(401, stale.getResponse().getStatus(), stale.getResponse().getContentAsString());
        assertEquals("SESSION_INVALID", errorOf(stale).path("code").asText());
    }

    private static String observationJson(String serial, String proof, String epoch, String seq)
            throws Exception {
        return writeJson(Map.of(
                "microcrystalSerial", serial,
                "connectionProof", proof,
                "capabilities", Map.of("schemaVersion", 1, "revision", "1"),
                "observationEpoch", epoch,
                "observationSeq", seq,
                "observedAt", Instant.now().toString(),
                "state", Map.of("mode", "idle")));
    }
}

package cn.yuanxin.mvp.web.devices;

import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.test.web.servlet.MvcResult;

import java.util.List;
import java.util.Map;
import java.util.UUID;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;

/**
 * 测试组 2-6：M2-A02 心跳顺序、越权、不越界、episode 稳定性、状态变化代次。
 */
class GimbalHeartbeatIT extends AbstractDeviceIT {

    private MvcResult heartbeat(String token, UUID gimbalId, String epoch, String seq,
                                Object incidents) throws Exception {
        return mockMvc.perform(post("/api/v1/gimbals/" + gimbalId + "/heartbeats")
                        .header("Authorization", "Bearer " + token)
                        .contentType("application/json")
                        .content(heartbeatJson(epoch, seq, "awake", null, null, incidents)))
                .andReturn();
    }

    private Map<String, Object> row(UUID gimbalId) {
        return jdbc.queryForMap("SELECT last_seen_at, status_revision, connection_status,"
                + " latest_observation::text AS obs, active_incidents::text AS incidents"
                + " FROM gimbals WHERE id = ?", gimbalId);
    }

    @Test
    @DisplayName("测试组 2：seq 推进；重放/迟到不推进；新 epoch 重置基准")
    void orderingRejectsStaleAndDuplicate() throws Exception {
        GimbalSession session = gimbalSession();
        UUID gimbalId = session.gimbalId();
        String token = session.accessToken();

        assertEquals(200, heartbeat(token, gimbalId, "epoch-1", "1", null)
                .getResponse().getStatus());
        assertTrue(dataOf(heartbeat(token, gimbalId, "epoch-1", "2", null))
                .path("accepted").asBoolean());
        assertTrue(dataOf(heartbeat(token, gimbalId, "epoch-1", "3", null))
                .path("accepted").asBoolean());

        Map<String, Object> before = row(gimbalId);
        MvcResult duplicate = heartbeat(token, gimbalId, "epoch-1", "2", null);
        assertEquals(200, duplicate.getResponse().getStatus());
        assertFalse(dataOf(duplicate).path("accepted").asBoolean());
        // 旧/重复心跳返回当前后端 lastSeenAt，且 DB 逐列未变
        assertEquals(((java.sql.Timestamp) before.get("last_seen_at")).toInstant().toString(),
                java.time.Instant.parse(dataOf(duplicate).path("lastSeenAt").asText()).toString());
        assertEquals(before, row(gimbalId));

        MvcResult late = heartbeat(token, gimbalId, "epoch-1", "1", null);
        assertFalse(dataOf(late).path("accepted").asBoolean());
        assertEquals(before, row(gimbalId));

        // 不同 epoch = 新来源会话，小 seq 也接受（不跨来源比较裸序号）
        MvcResult newEpoch = heartbeat(token, gimbalId, "epoch-2", "1", null);
        assertTrue(dataOf(newEpoch).path("accepted").asBoolean());
        assertFalse(before.get("last_seen_at").equals(row(gimbalId).get("last_seen_at")));
    }

    @Test
    @DisplayName("测试组 3：APP → 403；他人云台/不存在 → 不可区分 404；无 token → 401")
    void authorization() throws Exception {
        GimbalSession a = gimbalSession();
        GimbalSession b = gimbalSession();
        String appToken = loginApp(newPhone()).accessToken();

        MvcResult app = heartbeat(appToken, a.gimbalId(), "e", "1", null);
        assertEquals(403, app.getResponse().getStatus());
        assertEquals("CALLER_NOT_ALLOWED", errorOf(app).path("code").asText());

        MvcResult foreign = heartbeat(b.accessToken(), a.gimbalId(), "e", "1", null);
        MvcResult missing = heartbeat(b.accessToken(), UUID.randomUUID(), "e", "1", null);
        assertIndistinguishableError(foreign, missing);
        assertEquals(404, foreign.getResponse().getStatus());
        assertEquals("RESOURCE_NOT_VISIBLE", errorOf(foreign).path("code").asText());

        MvcResult anonymous = mockMvc.perform(post("/api/v1/gimbals/" + a.gimbalId() + "/heartbeats")
                        .contentType("application/json")
                        .content(heartbeatJson("e", "1", "awake", null, null, null)))
                .andReturn();
        assertEquals(401, anonymous.getResponse().getStatus());
    }

    @Test
    @DisplayName("测试组 4：taskId/executionId 只作观察，不移动指针/不建执行/不建 job/不建通知")
    void heartbeatDoesNotCrossIntoTaskState() throws Exception {
        GimbalSession session = gimbalSession();
        UUID gimbalId = session.gimbalId();
        long executions = count("care_executions", "controller_gimbal_id = ?", gimbalId);
        long jobs = count("async_jobs", "owner_id = ?", gimbalId);
        long notifications = count("notifications", "gimbal_id = ?", gimbalId);

        MvcResult result = mockMvc.perform(post("/api/v1/gimbals/" + gimbalId + "/heartbeats")
                        .header("Authorization", "Bearer " + session.accessToken())
                        .contentType("application/json")
                        .content(heartbeatJson("e", "1", "awake", UUID.randomUUID(),
                                UUID.randomUUID(), null)))
                .andReturn();
        assertEquals(200, result.getResponse().getStatus());
        assertTrue(dataOf(result).path("accepted").asBoolean());

        Map<String, Object> row = jdbc.queryForMap("SELECT current_assessment_id,"
                + " current_assessment_revision, latest_observation::text AS obs"
                + " FROM gimbals WHERE id = ?", gimbalId);
        assertNull(row.get("current_assessment_id"));
        assertEquals(0L, ((Number) row.get("current_assessment_revision")).longValue());
        JsonNode observed = JSON.readTree((String) row.get("obs"));
        assertNotNull(observed.path("task_ref").asText(null));
        assertEquals(executions, count("care_executions", "controller_gimbal_id = ?", gimbalId));
        assertEquals(jobs, count("async_jobs", "owner_id = ?", gimbalId));
        assertEquals(notifications, count("notifications", "gimbal_id = ?", gimbalId));
    }

    @Test
    @DisplayName("测试组 5：同 code 一个 episode、同一 incidentId；清除 resolved；再现新 ID")
    void episodesAreStable() throws Exception {
        GimbalSession session = gimbalSession();
        UUID gimbalId = session.gimbalId();
        String token = session.accessToken();
        List<Map<String, Object>> incident = List.of(Map.of("code", "OVERHEAT", "severity", "high"));

        for (int seq = 1; seq <= 3; seq++) {
            assertTrue(dataOf(heartbeat(token, gimbalId, "e", String.valueOf(seq), incident))
                    .path("accepted").asBoolean());
        }
        JsonNode active = JSON.readTree((String) row(gimbalId).get("incidents")).path("episodes");
        assertEquals(1, active.size());
        String firstId = active.fieldNames().next();
        assertEquals("active", active.path(firstId).path("state").asText());

        // 报清除
        MvcResult cleared = heartbeat(token, gimbalId, "e", "4",
                List.of(Map.of("code", "OVERHEAT", "state", "cleared")));
        assertEquals(200, cleared.getResponse().getStatus());
        JsonNode afterClear = JSON.readTree((String) row(gimbalId).get("incidents")).path("episodes");
        assertEquals(1, afterClear.size());
        assertEquals("resolved", afterClear.path(firstId).path("state").asText());
        assertFalse(afterClear.path(firstId).path("resolved_at").isNull());

        // 再现同 code → 新 incidentId
        heartbeat(token, gimbalId, "e", "5", List.of(Map.of("code", "OVERHEAT")));
        JsonNode afterReoccur = JSON.readTree((String) row(gimbalId).get("incidents")).path("episodes");
        assertEquals(2, afterReoccur.size());
        String secondId = null;
        for (var it = afterReoccur.fieldNames(); it.hasNext(); ) {
            String id = it.next();
            if (!id.equals(firstId)) {
                secondId = id;
            }
        }
        assertNotNull(secondId);
        assertEquals("active", afterReoccur.path(secondId).path("state").asText());
    }

    @Test
    @DisplayName("测试组 6：unknown→online 时 status_revision +1；同状态不递增")
    void statusRevisionOnlyOnConnectionChange() throws Exception {
        GimbalSession session = gimbalSession();
        UUID gimbalId = session.gimbalId();
        String token = session.accessToken();

        heartbeat(token, gimbalId, "e", "1", null);
        Map<String, Object> afterFirst = row(gimbalId);
        assertEquals("online", afterFirst.get("connection_status"));
        assertEquals(1L, ((Number) afterFirst.get("status_revision")).longValue());

        heartbeat(token, gimbalId, "e", "2", null);
        assertEquals(1L, ((Number) row(gimbalId).get("status_revision")).longValue());
    }
}

