    @Test
    @DisplayName("测试组 12：解绑递增代次、幂等不递增、旧解绑不删新绑定、不触碰授权/报告/任务/微晶")
    void unbindSemantics() throws Exception {
        LoginResult a = loginAppWithInstallation(newPhone(), "inst-unbind-a");
